"use client";
import { useCallback, useEffect, useRef, useState } from "react";
import { Activity, ArrowDown, ArrowLeftRight, ArrowRight, BookOpen, Check, CheckCircle2, ChevronDown, ChevronRight, CircleHelp, Clock3, Download, ExternalLink, Fingerprint, GitBranch, Layers3, LockKeyhole, PackageCheck, Play, Plus, RefreshCw, RotateCcw, ShieldCheck, Sparkles, Wallet, X } from "lucide-react";
import type { Workspace } from "../../packages/contracts";
import { SAMPLE_SCENARIOS, type CompensationRequest, type KitAmendment, type KitCommitment, type RepairBundle, type RepairCandidate, type RepairRun, type RepairView, type SampleScenario } from "../../packages/living-repair/contracts";
import { DeviceArt } from "./device-art";
import { ModalFrame } from "./modal";
import { api, Busy, currency, downloadJSON, shortTime } from "./ui";

type Detail = "change" | "evidence" | "history";
type Dialog = { kind: "sample" } | { kind: "next-sample" } | { kind: "baseline"; candidateId: string } | { kind: "accept"; authority: "buyer" | "policy" } | { kind: "policy" } | { kind: "prepare-compensation"; purpose: "undo" | "failed_commit" } | { kind: "compensation"; id: string } | { kind: "shipment" } | { kind: "support" };
type Result = { result: unknown; repair: RepairView };
const activePhases = ["queued", "refreshing", "discovering", "verifying"];
const statusNames: Record<string, string> = { queued: "Saved for discovery", refreshing: "Refreshing the exact offer", discovering: "Finding alternatives", verifying: "Checking every premise", ready: "Ready to review", needs_evidence: "Evidence still open", no_alternative: "No exact alternative", resolved: "The earlier change is resolved", not_in_kit: "Place in your kit first", protected: "Owned equipment protected", stale: "A fresh proposal is needed", failed: "Discovery needs attention", cancelled: "Proposal closed", proposed: "Your decision", awaiting_consent: "Fresh consent needed", requires_payment_approval: "Payment approval needed", payment_pending: "Reconciling payment", ready_to_commit: "Confirming commitment", committed: "Kit change complete", compensation_required: "Compensation needed", compensating: "Compensation in progress", compensated: "Payment compensated", undo_pending: "Restoration in progress", undone: "Original kit restored", partial_support_needed: "Separate support review", refused: "Operation refused" };
const readable = (value: string) => statusNames[value] ?? value.replaceAll("_", " ");
function SourcePill({ source, payment = false }: { source: string; payment?: boolean }) { return <span className={`repair-source ${source === "sample" ? "sample" : "live"}`}>{source === "sample" ? "Sample" : source === "replay" ? "Replay" : payment ? "Live · PayPal sandbox" : "Observed catalog"}</span>; }
function MoneyDelta({ minor }: { minor: number }) { return <>{minor > 0 ? "+" : minor < 0 ? "−" : ""}{currency(Math.abs(minor))}</>; }

export function LivingRepair({ workspace, onRefresh, onEquipment, onWorkbench }: { workspace: Workspace; onRefresh: () => Promise<void>; onEquipment: () => void; onWorkbench: () => void }) {
  const [data, setData] = useState<RepairView | null>(null); const [selectedId, setSelectedId] = useState<string | null>(null); const [detail, setDetail] = useState<Detail>("change");
  const [busy, setBusy] = useState(""); const [error, setError] = useState(""); const [dialog, setDialog] = useState<Dialog | null>(null);
  const generation = useRef(0); const selected = useRef(selectedId); selected.current = selectedId; const mutating = useRef(false); const inflight = useRef(false); const initial = useRef<Promise<Result> | null>(null);
  const load = useCallback(async (force = false) => {
    if (inflight.current && !force || mutating.current) return; inflight.current = true; const ticket = ++generation.current;
    try { const result = await api<RepairView>(`/api/living-repair${selected.current ? `?run=${encodeURIComponent(selected.current)}` : ""}`); if (ticket === generation.current) { setData(result); setError(""); if (!selected.current && result.runs[0]) setSelectedId(result.runs[0].id); } }
    catch (error) { if (ticket === generation.current) setError(error instanceof Error ? error.message : "The saved repair could not be opened."); }
    finally { inflight.current = false; }
  }, []);
  useEffect(() => {
    let active = true; const params = new URL(window.location.href).searchParams; const incidentId = params.get("incident"); const runId = params.get("repair");
    if (runId && /^[a-f0-9-]{36}$/.test(runId)) { selected.current = runId; setSelectedId(runId); }
    initial.current ??= incidentId && /^[a-f0-9-]{36}$/.test(incidentId) ? api<Result>("/api/living-repair", "POST", { kind: "incident", incidentId }) : api<RepairView>(`/api/living-repair${selected.current ? `?run=${selected.current}` : ""}`).then(repair => ({ repair, result: null }));
    initial.current.then(result => { if (active) { setData(result.repair); const id = result.result && typeof result.result === "object" && "base" in result.result ? (result.result as RepairRun).id : selected.current ?? result.repair.runs[0]?.id ?? null; selected.current = id; setSelectedId(id); } }).catch(error => { if (active) setError(error.message); });
    return () => { active = false; generation.current++; };
  }, []);
  const waiting = Boolean(data?.runs.some(run => activePhases.includes(run.phase)) || data?.amendments.some(amendment => ["payment_pending", "ready_to_commit", "compensating", "undo_pending"].includes(amendment.status)));
  useEffect(() => {
    let timer: ReturnType<typeof setTimeout>; let active = true;
    const next = () => { timer = setTimeout(async () => { if (document.visibilityState === "visible") await load(); if (active) next(); }, waiting ? 3500 : 20_000); };
    next(); const visible = () => { if (document.visibilityState === "visible") void load(); }; document.addEventListener("visibilitychange", visible);
    return () => { active = false; clearTimeout(timer); document.removeEventListener("visibilitychange", visible); };
  }, [waiting, load]);
  function selectRun(id: string) { generation.current++; setData(null); selected.current = id; setSelectedId(id); setDetail("change"); setError(""); const url = new URL(window.location.href); url.searchParams.set("repair", id); url.searchParams.delete("incident"); window.history.replaceState(null, "", url); void load(true); }
  async function perform(body: Record<string, unknown>, label: string): Promise<unknown> {
    if (mutating.current) { const message = "Your previous decision is still being saved. Wait for its result before continuing."; setError(message); throw new Error(message); } mutating.current = true; generation.current++; setBusy(label); setError("");
    try {
      const response = await api<Result>(`/api/living-repair${selected.current ? `?run=${encodeURIComponent(selected.current)}` : ""}`, "POST", body); generation.current++; setData(response.repair);
      const result = response.result;
      if (result && typeof result === "object") {
        if ("base" in result) { const run = result as RepairRun; selected.current = run.id; setSelectedId(run.id); const url = new URL(window.location.href); url.searchParams.set("repair", run.id); url.searchParams.delete("incident"); window.history.replaceState(null, "", url); }
        if ("status" in result && ["committed", "undone"].includes(String(result.status)) || "state" in result && result.state === "completed") await onRefresh();
      }
      return result;
    } catch (error) { const message = error instanceof Error ? error.message : "This action was not completed. Your saved record remains available."; setError(message); throw error; }
    finally { mutating.current = false; setBusy(""); }
  }
  const act = (body: Record<string, unknown>, label: string) => { void perform(body, label).catch(() => undefined); };
  const run = data?.run ?? undefined;
  const candidates = data?.candidates.filter(candidate => candidate.runId === run?.id).sort((a, b) => a.rank - b.rank) ?? [];
  const amendment = data?.amendments.find(amendment => amendment.proposal.id === run?.amendmentId);
  const candidate = candidates.find(candidate => candidate.id === run?.selectedCandidateId) ?? candidates[0];
  const commitment = data?.commitments.find(commitment => commitment.id === run?.commitmentId);
  const policy = data?.policies.find(policy => policy.commitmentId === commitment?.id && !policy.revokedAt && Date.parse(policy.expiresAt) > Date.now());
  const order = data?.orders.find(order => order.id === amendment?.orderId);
  const compensation = data?.compensations.find(request => request.amendmentId === amendment?.proposal.id);
  async function propose(value: RepairCandidate) {
    if (!run) return;
    if (!commitment) { setDialog({ kind: "baseline", candidateId: value.id }); return; }
    await perform({ kind: "propose", runId: run.id, candidateId: value.id, candidateDigest: value.digest }, "Saving the exact before-and-after proposal…");
  }
  return <section className="repair-workshop" aria-labelledby="repair-workshop-title">
    <header className="repair-intro"><div><span className="eyebrow"><GitBranch size={12}/> LIVING REPAIR</span><h3 id="repair-workshop-title">One change. The whole kit considered.</h3><p>Trace what’s affected, compare a sourced alternative, and keep control of the commitment.</p></div><div><button className="button subtle" onClick={() => setDialog({ kind: "sample" })}><Play size={13}/> Try a Sample scenario</button><button className="icon-button" aria-label="Refresh saved repairs" disabled={Boolean(busy)} onClick={() => void load()}><RefreshCw size={16}/></button></div></header>
    {error && <div className="repair-alert" role="alert"><CircleHelp size={18}/><p>{error}</p><button className="icon-button" aria-label="Dismiss repair error" onClick={() => setError("")}><X size={15}/></button></div>}
    {busy && !dialog && <div className="repair-action-progress" role="status"><Busy text={busy}/></div>}
    <p className="sr-only" role="status" aria-live="polite">{busy || compensation?.reason || amendment?.reason || run?.reason || ""}</p>
    {!data ? <div className="repair-loading"><Busy text="Opening saved repairs and their evidence…"/></div> : !run ? <div className="repair-welcome"><div className="repair-welcome-copy"><span className="eyebrow">THE SHOW CAN GO ON</span><h3>A missing piece.<br/>A considered next move.</h3><p>A fresh market observation can start a repair. Every proposal keeps your brief and owned gear in view, with a separate decision before money or a kit commitment changes.</p><button className="button" onClick={() => setDialog({ kind: "sample" })}>Open the repair workshop <ArrowRight size={15}/></button><div className="repair-welcome-note"><Fingerprint size={15}/><span>No live repair is waiting. The workshop creates a clearly labelled Sample branch.</span></div></div><div className="repair-welcome-art"><RepairBoard bundle={{ kit: workspace.kit, certificate: workspace.certificate, profiles: workspace.profiles, sources: workspace.sources }} componentId="audio" label="THE WHOLE PROMISE"/><div className="repair-art-caption"><span><ShieldCheck size={14}/> Keep the brief</span><span><LockKeyhole size={14}/> Protect owned gear</span><span><Wallet size={14}/> Scope every payment</span></div></div></div> : <div className="repair-shell">
      <aside className="repair-run-list" aria-label="Saved repairs"><header><span className="eyebrow">YOUR REPAIR HISTORY</span><span>{data.runs.length}</span></header>{data.runs.map(item => { const change = data.amendments.find(amendment => amendment.proposal.id === item.amendmentId); const state = change?.status ?? item.amendmentStatus ?? item.phase; return <button key={item.id} className={run.id === item.id ? "selected" : ""} aria-current={run.id === item.id ? "true" : undefined} onClick={() => selectRun(item.id)}><div><SourcePill source={item.sourceMode}/><ChevronRight size={12}/></div><b>{item.title}</b><span className={`repair-run-state ${state}`}>{["committed", "undone", "compensated"].includes(state) ? <CheckCircle2 size={12}/> : activePhases.includes(state) ? <RefreshCw size={12} className="spin"/> : <Activity size={12}/>} {readable(state)}</span><time dateTime={item.createdAt}>{shortTime(item.createdAt)}</time></button>; })}<div className="repair-history-note"><Layers3 size={20}/><p>Original graphs, quotes and money records stay in the history.</p></div></aside>
      <div className="repair-active"><header className="repair-heading"><div><div className="repair-heading-meta"><SourcePill source={run.sourceMode}/><span>{commitment?.branch === "sample_demonstration" ? "Separate demonstration branch" : "Exact saved kit"}</span></div><h3>{run.title}</h3><p>{amendment?.reason ?? run.reason}</p></div><button className="icon-button" aria-label="Download the safe repair record" onClick={() => downloadJSON({ run, candidates, amendment, commitment, compensation, financialOrders: data.orders.filter(order => order.livingRepair?.amendmentId === amendment?.proposal.id) }, `worldkit-repair-${run.id.slice(0, 8)}.json`)}><Download size={17}/></button></header>
      <RepairProgress run={run} amendment={amendment}/>
      <div className="repair-content-grid"><div className="repair-main"><div className="repair-detail-nav" role="group" aria-label="Repair detail"><button className={detail === "change" ? "active" : ""} aria-pressed={detail === "change"} onClick={() => setDetail("change")}><ArrowLeftRight size={14}/> The change</button><button className={detail === "evidence" ? "active" : ""} aria-pressed={detail === "evidence"} onClick={() => setDetail("evidence")}><BookOpen size={14}/> The evidence</button><button className={detail === "history" ? "active" : ""} aria-pressed={detail === "history"} onClick={() => setDetail("history")}><Clock3 size={14}/> The record</button></div>
      {detail === "change" && <>
        <div className="repair-comparison"><div className="repair-comparison-label"><span><i/> ORIGINAL PROMISE</span><b>{candidate?.kind === "merchant_change" ? "Same equipment. Fresh sourcing." : "Every path gets another look."}</b></div><RepairBoard bundle={amendment?.proposal.after ?? candidate?.bundle ?? run.base} componentId={run.impact.changedComponentIds[0] ?? "audio"} label={candidate ? "PROPOSED CONFIGURATION" : "SAVED CONFIGURATION"}/><div className="repair-before-after"><div><span className="eyebrow">BEFORE</span><b>{run.base.profiles.find(profile => profile.id === run.base.kit.components.find(component => component.id === run.impact.changedComponentIds[0])?.profileId)?.model ?? "Your saved kit"}</b><small>{run.affectedDomain}</small></div><span className="repair-swap-arrow"><ArrowRight size={17}/></span><div><span className="eyebrow">{amendment?.status === "committed" ? "COMMITTED" : "PROPOSED"}</span><b>{candidate?.bundle.profiles.find(profile => profile.id === candidate.afterProfileId)?.model ?? "Finding an exact alternative"}</b><small>{candidate?.offer.domain ?? "Current stock and evidence first"}</small></div></div></div>
        <div className="repair-preserved"><span><LockKeyhole size={14}/> {run.impact.protectedComponentIds.length} owned pieces preserved</span><span><ShieldCheck size={14}/> Hard brief unchanged</span><button onClick={() => setDetail("evidence")}>{run.impact.requirementIds.length} requirements rechecked <ArrowRight size={12}/></button></div>
        {activePhases.includes(run.phase) && <div className="repair-working"><span className="repair-working-orbit"><RefreshCw size={22} className="spin"/></span><div><b>{readable(run.phase)}</b><p>{run.reason}</p>{run.discovery.length > 0 && <progress value={run.discoveryCursor} max={run.discovery.length} aria-label="Alternative identities checked"/>}</div><button className="text-button" disabled={Boolean(busy)} onClick={() => act({ kind: "advance", runId: run.id }, "Continuing the saved discovery step…")}>Continue checks <ArrowRight size={12}/></button><button className="text-button" disabled={Boolean(busy)} onClick={() => act({ kind: "cancel_run", runId: run.id }, "Stopping the retained discovery…")}>Stop checks <X size={12}/></button></div>}
        {["not_in_kit", "protected", "resolved", "cancelled", "no_alternative", "stale", "failed"].includes(run.phase) && <div className="repair-gate"><CircleHelp size={22}/><div><h4>{readable(run.phase)}</h4><p>{run.reason}</p>{run.phase === "not_in_kit" ? <button className="text-button" onClick={onEquipment}>Open equipment passport <ArrowRight size={13}/></button> : run.phase === "protected" || run.phase === "stale" || run.phase === "resolved" ? <button className="text-button" onClick={onWorkbench}>Review the current workbench <ArrowRight size={13}/></button> : <button className="text-button" disabled={Boolean(busy)} onClick={() => act({ kind: "retry", runId: run.id }, "Queuing a fresh exact-product check…")}>Retry discovery <RefreshCw size={12}/></button>}</div></div>}
        {candidates.length > 0 && <section className="repair-candidates" aria-label="Sourced alternatives"><header><div><span className="eyebrow">SOURCE FIRST. THEN COMPARE.</span><h4>{candidates.length} exact {candidates.length === 1 ? "alternative" : "alternatives"}</h4></div><button className="text-button" disabled={Boolean(busy) || Boolean(amendment?.acceptedAt)} onClick={() => act({ kind: "retry", runId: run.id }, "Refreshing exact alternatives…")}><RefreshCw size={12}/> Refresh</button></header>{candidates.map(value => <article key={value.id} className={`${value.id === candidate?.id ? "selected" : ""} ${value.technicalState === "satisfied" ? "ready" : "open"}`}><div className="repair-candidate-art"><DeviceArt kind={value.bundle.profiles.find(profile => profile.id === value.afterProfileId)?.kind ?? "recorder"}/></div><div className="repair-candidate-copy"><div><span className="repair-candidate-kind">{value.kind === "merchant_change" ? "SAME EXACT PRODUCT" : "DIFFERENT EXACT MODEL"}</span><SourcePill source={value.evidence.mode}/></div><h4>{value.title}</h4><p>{value.offer.retailer} <span>·</span> {value.offer.condition} <span>·</span> In stock at last check</p><div className={`repair-check-label ${value.technicalState}`}><span>{value.technicalState === "satisfied" ? <Check size={12}/> : <CircleHelp size={12}/>}</span>{value.technicalState === "satisfied" ? value.evidence.mode === "sample" ? "Synthetic technical checks pass" : "Critical technical checks pass" : "Critical evidence remains open"}</div>{value.blockers[0] && <small>{value.blockers[0]}</small>}</div><div className="repair-candidate-action"><strong>{currency(value.offer.unitMinor)}<small> USD</small></strong><span>Retailer shipping unknown</span><button className="button subtle" disabled={Boolean(busy) || Boolean(amendment?.acceptedAt) || amendment?.proposal.candidateId === value.id && amendment.status !== "cancelled"} onClick={() => void propose(value).catch(() => undefined)}>{amendment?.proposal.candidateId === value.id && amendment.status !== "cancelled" ? "Proposal saved" : "Review this change"}<ArrowRight size={12}/></button></div></article>)}</section>}
      </>}
      {detail === "evidence" && <RepairEvidencePanel run={run} candidate={candidate} amendment={amendment}/>}
      {detail === "history" && <RepairHistory run={run} amendment={amendment} compensation={compensation} data={data}/>}
      </div><aside className="repair-authority-panel" aria-label="Kit change authority"><span className="eyebrow"><Wallet size={13}/> THE COMMITMENT</span><h3>Your call.<br/>Your limits.</h3>{amendment ? <><div className="repair-quote-total"><span>{amendment.proposal.quote.deltaMinor >= 0 ? "ADDITIONAL CONTROLLED COST" : "CONTROLLED PRICE CHANGE"}</span><strong><MoneyDelta minor={amendment.proposal.quote.deltaMinor}/><small> USD</small></strong></div><dl className="repair-quote-lines"><div><dt>Original controlled total</dt><dd>{currency(amendment.proposal.quote.beforeTotalMinor)}</dd></div><div><dt>Proposed controlled total</dt><dd>{currency(amendment.proposal.quote.afterTotalMinor)}</dd></div><div><dt>Test shipping / tax</dt><dd>$0 / $0</dd></div><div><dt>Quote valid until</dt><dd>{shortTime(amendment.proposal.expiresAt)}</dd></div></dl><div className={`repair-decision-state ${amendment.status}`}><span>{["committed", "undone", "compensated"].includes(amendment.status) ? <CheckCircle2 size={17}/> : <CircleHelp size={17}/>}</span><div><b>{readable(amendment.status)}</b><p>{amendment.reason}</p></div></div>
        {!amendment.acceptedAt && amendment.status !== "cancelled" && <><button className="button full" disabled={Boolean(busy) || amendment.proposal.technicalState !== "satisfied"} onClick={() => setDialog({ kind: "accept", authority: "buyer" })}>Review exact approval <ArrowRight size={14}/></button>{amendment.proposal.technicalState !== "satisfied" && <button className="text-button" onClick={() => setDetail("evidence")}>Inspect the open evidence <BookOpen size={13}/></button>}{policy && <button className="button subtle full" disabled={Boolean(busy) || amendment.proposal.technicalState !== "satisfied"} onClick={() => setDialog({ kind: "accept", authority: "policy" })}>Check my kit allowance <ShieldCheck size={14}/></button>}</>}
        {order && <div className="repair-money-record"><SourcePill source={order.sourceMode} payment/><div><span>Captured</span><b>{currency(order.capturedMinor)}</b></div><div><span>Refunded</span><b>{currency(order.refundedMinor)}</b></div>{order.approvalUrl && <a className="button paypal-button full" href={order.approvalUrl} rel="noreferrer">Continue in PayPal <ExternalLink size={13}/></a>}{amendment.acceptedAt && !order.capturedMinor && <button className="text-button" disabled={Boolean(busy)} onClick={() => act({ kind: "capture", amendmentId: amendment.proposal.id, acceptExactCapture: true }, "Checking the exact approved capture…")}>Confirm approved payment <ArrowRight size={12}/></button>}<button className="text-button" disabled={Boolean(busy)} onClick={() => act({ kind: "reconcile", amendmentId: amendment.proposal.id }, "Reading the original payment operation…")}><RefreshCw size={12}/> Reconcile original payment</button>{amendment.acceptedAt && !order.capturedMinor && ["payment_pending", "requires_payment_approval"].includes(amendment.status) && <button className="text-button" disabled={Boolean(busy)} onClick={() => act({ kind: "resume", amendmentId: amendment.proposal.id, proposalDigest: amendment.proposal.digest, continueSavedApproval: true }, "Continuing only the original saved approval…")}>Continue saved approval <ArrowRight size={12}/></button>}</div>}
        {amendment.status === "committed" && <div className="repair-aftercare"><button className="button subtle full" disabled={Boolean(busy)} onClick={() => { setError(""); setDialog({ kind: "prepare-compensation", purpose: "undo" }); }}><RotateCcw size={14}/> Review conditional undo</button>{commitment?.branch === "sample_demonstration" && commitment.latestAmendmentId === amendment.proposal.id && commitment.lines.every(line => line.fulfillment === "unfulfilled") && <button className="text-button" disabled={Boolean(busy)} onClick={() => setDialog({ kind: "next-sample" })}><Play size={13}/> Try the next $20 change</button>}<p>Within 24 hours, while unfulfilled. Original stock, price and technical evidence must still permit restoration.</p>{commitment?.branch === "sample_demonstration" && <button className="text-button" disabled={Boolean(busy)} onClick={() => setDialog({ kind: "shipment" })}><PackageCheck size={13}/> Simulate shipment</button>}</div>}
        {amendment.status === "compensation_required" && <button className="button full" disabled={Boolean(busy)} onClick={() => { setError(""); setDialog({ kind: "prepare-compensation", purpose: "failed_commit" }); }}>Review separate compensation <ArrowRight size={14}/></button>}
        {["partial_support_needed", "refused", "stale", "compensation_required"].includes(amendment.status) && <button className="text-button" disabled={Boolean(busy)} onClick={() => setDialog({ kind: "support" })}><BookOpen size={13}/> Save a private review request</button>}{compensation && <div className="repair-compensation-mini"><span className="eyebrow">COMPENSATION RECORD</span><b>{compensation.state.replaceAll("_", " ")}</b><p>{compensation.reason}</p><button className="text-button" onClick={() => setDialog({ kind: "compensation", id: compensation.id })}>Open exact record <ArrowRight size={12}/></button></div>}
      </> : <div className="repair-no-quote"><span><Fingerprint size={25}/></span><b>A proposal comes before permission.</b><p>Choose an exact alternative to see the whole controlled cost and immutable before-and-after record.</p></div>}
      {commitment && <div className="repair-policy-card"><div><ShieldCheck size={17}/><b>A separate kit allowance</b></div>{policy ? <><div className="repair-policy-amount"><strong>{currency(policy.remainingMinor)}</strong><span>of {currency(policy.capMinor)} remaining</span></div><div className="repair-policy-meter" role="img" aria-label={`${currency(policy.consumedMinor)} consumed and ${currency(policy.pendingMinor)} pending of ${currency(policy.capMinor)}`}><i style={{ width: `${Math.min(100, policy.consumedMinor / policy.capMinor * 100)}%` }}/><i className="pending" style={{ width: `${Math.min(100, policy.pendingMinor / policy.capMinor * 100)}%` }}/></div><p>{currency(policy.consumedMinor)} gross used · {currency(policy.pendingMinor)} pending. Refunds do not refill the allowance.</p><SourcePill source={policy.paymentMode} payment/><button className="text-button" disabled={Boolean(busy)} onClick={() => act({ kind: "revoke_policy", policyId: policy.id }, "Stopping future automatic kit charges…")}>Stop this allowance</button></> : <><p>Fresh scope for this controlled kit, its sourcing retailers and equipment categories. A saved wallet alone grants no authority.</p><button className="text-button" disabled={Boolean(busy) || !amendment || Boolean(commitment.lines.some(line => line.fulfillment !== "unfulfilled"))} onClick={() => setDialog({ kind: "policy" })}>Set a fresh kit limit <Plus size={13}/></button></>}</div>}
      <div className="repair-boundary"><Layers3 size={16}/><p><b>WorldKit Studio · controlled demonstration.</b> The starting commitment is Sample and has no assumed payment. Channel3 supplies offers; retailer orders, reservations and fulfillment are outside this flow. The digital setup service has separate authority.</p></div>{busy && <div className="repair-panel-busy"><Busy text={busy}/></div>}</aside></div></div>
    </div>}
    {dialog && <RepairDialog key={`${dialog.kind}:${dialog.kind === "compensation" ? dialog.id : ""}`} dialog={dialog} data={data} run={run} candidate={candidate} amendment={amendment} commitment={commitment} policy={policy} busy={busy} error={error} onClose={() => { if (!busy) setDialog(null); }} onAction={async body => {
      if (body.kind === "prepare_compensation") { const result = await perform(body, "Checking original stock, current cost and refundable money…") as CompensationRequest; setDialog({ kind: "compensation", id: result.id }); return; }
      if (dialog.kind === "baseline" && run) { await perform(body, "Saving the explicit Sample merchant baseline…"); const chosen = candidates.find(value => value.id === dialog.candidateId); if (chosen) await perform({ kind: "propose", runId: run.id, candidateId: chosen.id, candidateDigest: chosen.digest }, "Saving the exact controlled proposal…"); }
      else await perform(body, "Saving and checking this exact decision…"); setDialog(null);
    }}/>}<footer className="repair-scope-note"><ShieldCheck size={14}/><p>Technical checks describe a computational model. Sample assertions do not establish human review or physical performance. Retailer landed costs stay separate from the controlled merchant quote.</p></footer>
  </section>;
}

function RepairProgress({ run, amendment }: { run: RepairRun; amendment?: KitAmendment }) {
  const steps = [{ label: "Observe", done: true }, { label: "Trace", done: run.steps.some(step => step.id === "impact") }, { label: "Source", done: run.steps.some(step => step.id === "discover") }, { label: "Verify", done: run.phase === "ready" || Boolean(amendment?.proposal.technicalState === "satisfied") }, { label: "Authorize", done: Boolean(amendment?.acceptedAt) }, { label: "Commit", done: Boolean(amendment?.committedAt) }];
  return <ol className="repair-progress" aria-label="Repair progress">{steps.map((step, index) => <li key={step.label} className={step.done ? "done" : ""}><span>{step.done ? <Check size={11}/> : String(index + 1).padStart(2, "0")}</span><b>{step.label}</b></li>)}</ol>;
}
function RepairBoard({ bundle, componentId, label }: { bundle: RepairBundle; componentId: string; label: string }) {
  const focus = bundle.kit.components.find(component => component.id === componentId) ?? bundle.kit.components.find(component => component.role === "audio");
  const profile = bundle.profiles.find(profile => profile.id === focus?.profileId);
  const owned = bundle.kit.components.filter(component => component.owned).slice(0, 3);
  return <div className="repair-board" aria-label={`${label}: ${profile?.model ?? "saved kit"} stays connected to the owned equipment`}><span className="repair-board-label">{label}</span><div className="repair-board-grid" aria-hidden="true"/><svg className="repair-board-wires" viewBox="0 0 650 230" preserveAspectRatio="none" aria-hidden="true"><path d="M84 58H178Q202 58 202 82V108H306M84 174H178Q202 174 202 150V122H306" stroke="#6b92cb"/><path d="M342 112H423Q446 112 446 58H555" stroke="#5c9c8c"/><path d="M342 112H555" stroke="#9f8bc6"/><path d="M342 112H423Q446 112 446 174H555" stroke="#c4a466"/></svg><div className="repair-board-voices"><span><DeviceArt kind="microphone"/><i>VOICE 01</i></span><span><DeviceArt kind="microphone"/><i>VOICE 02</i></span></div><div className="repair-board-focus"><span className="repair-board-halo"/><DeviceArt kind={profile?.kind ?? "recorder"}/><b>{profile?.model ?? "Exact identity needed"}</b><span className="repair-focus-tag"><ArrowLeftRight size={10}/> CHANGED PIECE</span></div><div className="repair-board-owned">{owned.map(component => { const item = bundle.profiles.find(profile => profile.id === component.profileId); return <span key={component.id}><DeviceArt kind={item?.kind ?? "host"}/><i><LockKeyhole size={8}/> {component.role === "monitor" ? "HEADPHONES" : component.role.toUpperCase()}</i></span>; })}</div></div>;
}
function RepairEvidencePanel({ run, candidate, amendment }: { run: RepairRun; candidate?: RepairCandidate; amendment?: KitAmendment }) {
  const bundle = amendment?.proposal.after ?? candidate?.bundle ?? run.base; const checks = amendment?.proposal.criticalChecks ?? candidate?.criticalChecks ?? [];
  return <div className="repair-evidence"><header><span className="eyebrow">FOLLOW EVERY PREMISE</span><h3>The reasons travel with the change.</h3><p>{run.catalogMode === "sample" ? "These are synthetic fixture assertions in a separate Sample branch. They demonstrate the checks without approving a real manufacturer fact." : "Exact source identities, recorded review and typed connections travel with this proposal. Uncertainty remains visible and blocks payment."}</p></header><div className="repair-evidence-summary"><div><strong>{run.impact.componentIds.length}</strong><span>pieces in the dependency closure</span></div><div><strong>{checks.filter(check => check.state === "satisfied").length}<small>/{checks.length}</small></strong><span>critical premises satisfied</span></div><div><strong>{bundle.certificate.counts.unknown}</strong><span>whole-kit questions remain</span></div></div><section><h4>The original hard brief</h4>{bundle.certificate.results.map(result => <article className={`repair-witness ${result.status}`} key={result.id}><span>{result.status === "satisfied" ? <Check size={14}/> : <CircleHelp size={14}/>}</span><div><b>{bundle.kit.goal.requirements.find(requirement => requirement.id === result.requirementId)?.label}</b><p>{result.explanation}</p>{result.componentIds.length > 0 && <small>{result.componentIds.join(" · ")}</small>}</div><em>{result.status === "satisfied" ? "Model pass" : result.status === "unknown" ? "Open" : "Conflict"}</em></article>)}</section><section><h4>Critical fact checks</h4>{checks.length ? checks.map((check, index) => <details className={`repair-fact ${check.state}`} key={`${check.factId}:${index}`}><summary><span>{check.state === "satisfied" ? <Check size={12}/> : <CircleHelp size={12}/>}</span><b>{check.property.replace(/([A-Z])/g, " $1")}</b><ChevronDown size={13}/></summary><p>{check.reason}</p><small>{bundle.profiles.find(profile => profile.id === check.profileId)?.model}</small>{check.sourceIds.map(id => { const source = bundle.sources.find(source => source.id === id); return source ? <div className="repair-fact-source" key={id}><BookOpen size={13}/><div><b>{source.title}</b><span>{source.publisher} · {source.kind === "sample" ? "Synthetic source" : source.kind.replaceAll("_", " ")}</span>{source.kind !== "sample" && <a href={source.url} target="_blank" rel="noreferrer">Open primary source <ExternalLink size={11}/></a>}<code>{source.contentHash}</code></div></div> : <p key={id}>Source identity {id} is unavailable.</p>; })}</details>) : <p className="repair-empty-checks">Critical checks appear after exact alternatives are retrieved.</p>}</section><div className="repair-hash-note"><Fingerprint size={14}/><div><b>Saved graph identity</b><code>{bundle.certificate.graphHash}</code><span>Rule set {bundle.certificate.ruleVersion} · physical performance not tested</span></div></div></div>;
}
function RepairHistory({ run, amendment, compensation, data }: { run: RepairRun; amendment?: KitAmendment; compensation?: CompensationRequest; data: RepairView }) {
  const orders = data.orders.filter(order => order.livingRepair?.amendmentId === amendment?.proposal.id);
  return <div className="repair-record"><header><span className="eyebrow">A CONTINUOUS, HONEST RECORD</span><h3>Every step keeps its receipts.</h3><p>Payment, kit commitment and restoration are separate facts. A failure in one cannot erase the others.</p></header><ol>{run.steps.map(step => <li key={step.id}><span className={step.state}><Check size={13}/></span><div><time dateTime={step.at}>{shortTime(step.at)}</time><h4>{step.title}</h4><p>{step.detail}</p></div></li>)}{amendment && <li><span><Fingerprint size={13}/></span><div><time dateTime={amendment.proposal.createdAt}>{shortTime(amendment.proposal.createdAt)}</time><h4>Exact amendment saved</h4><p>The graph, critical checks, source observations and quote have an immutable digest.</p><code>{amendment.proposal.digest}</code></div></li>}{amendment?.acceptedAt && <li><span><Wallet size={13}/></span><div><time dateTime={amendment.acceptedAt}>{shortTime(amendment.acceptedAt)}</time><h4>Separate financial authority accepted</h4><p>{amendment.policyId ? "Bound to this controlled kit’s fresh allowance, wallet consent and gross claim." : "Buyer approval binds only this exact amendment and its quoted additional cost."}</p></div></li>}{orders.map(order => <li key={order.id}><span><Wallet size={13}/></span><div><SourcePill source={order.sourceMode} payment/><h4>{order.livingRepair?.compensationId ? "Restoration supplement" : "Amendment payment"} · {readable(order.state)}</h4><p>{currency(order.capturedMinor)} captured · {currency(order.refundedMinor)} refunded. Gross history is retained.</p><small>Order {order.id}</small>{order.captureId && <code>Capture {order.captureId}</code>}{order.error && <p>{order.error}</p>}</div></li>)}{amendment?.committedAt && <li><span className="complete"><GitBranch size={13}/></span><div><time dateTime={amendment.committedAt}>{shortTime(amendment.committedAt)}</time><h4>Controlled commitment version {amendment.committedVersion}</h4><p>The saved graph and merchant lines changed together. The previous version remains available.</p></div></li>}{compensation && <li><span><RotateCcw size={13}/></span><div><time dateTime={compensation.createdAt}>{shortTime(compensation.createdAt)}</time><h4>Compensation · {compensation.state.replaceAll("_", " ")}</h4><p>{compensation.reason}</p><small>{currency(compensation.refundedMinor)} confirmed refunded · {currency(compensation.supplementalMinor)} supplemental quote</small></div></li>}</ol><div className="repair-record-footnote"><Activity size={15}/><p>{run.incidentIds.length ? `${run.incidentIds.length} retained market ${run.incidentIds.length === 1 ? "observation" : "observations"} converge on this repair cause.` : "This is an explicitly initiated Sample scenario. No authentic provider notification or signature is invented."}</p></div></div>;
}

function RepairDialog({ dialog, data, run, amendment, commitment, policy, busy, error, onClose, onAction }: { dialog: Dialog; data: RepairView | null; run?: RepairRun; candidate?: RepairCandidate; amendment?: KitAmendment; commitment?: KitCommitment; policy?: RepairView["policies"][number]; busy: string; error: string; onClose: () => void; onAction: (body: Record<string, unknown>) => Promise<void> }) {
  const [accepted, setAccepted] = useState(false); const [mode, setMode] = useState<"sample" | "live_sandbox">(run?.sourceMode === "sample" || dialog.kind === "sample" ? "sample" : "live_sandbox");
  const [scenario, setScenario] = useState<SampleScenario>("available-alternative"); const [cap, setCap] = useState("25"); const [walletId, setWalletId] = useState(""); const [supportMessage, setSupportMessage] = useState(""); const requestId = useRef(crypto.randomUUID());
  const request = dialog.kind === "compensation" ? data?.compensations.find(request => request.id === dialog.id) : undefined;
  const wallet = data?.wallets.find(wallet => wallet.id === walletId); const wallets = data?.wallets.filter(wallet => wallet.state === "active" && !wallet.revokedAt && Date.parse(wallet.expiresAt) > Date.now()) ?? [];
  const title = dialog.kind === "sample" ? "Give the kit a little plot twist." : dialog.kind === "next-sample" ? "One more change. The same limit." : dialog.kind === "support" ? "Keep the unresolved pieces together." : dialog.kind === "baseline" ? "Meet your controlled merchant." : dialog.kind === "policy" ? "Set a limit for this whole kit." : dialog.kind === "shipment" ? "Move the Sample kit into fulfillment." : dialog.kind === "prepare-compensation" ? dialog.purpose === "undo" ? "Explore the way back." : "Review the paid change." : dialog.kind === "compensation" ? request?.kind === "undo" ? "Check the way back." : "Resolve the paid change." : "A specific change. A fresh decision.";
  const submit = (body: Record<string, unknown>) => { void onAction(body).catch(() => undefined); };
  const allowanceMode = dialog.kind === "accept" && dialog.authority === "policy" ? policy?.paymentMode ?? mode : mode;
  return <ModalFrame labelledBy="repair-dialog-title" onClose={onClose} className="repair-dialog"><button className="modal-close icon-button" aria-label="Close repair decision" disabled={Boolean(busy)} onClick={onClose}><X size={18}/></button><span className="eyebrow"><GitBranch size={13}/> LIVING REPAIR · YOUR DECISION</span><h2 id="repair-dialog-title">{title}</h2>
    {dialog.kind === "prepare-compensation" && amendment && <><p>{dialog.purpose === "undo" ? "Restoration depends on the original exact item’s current stock, price and technical evidence. The kit must still be unfulfilled and within its 24-hour window." : "The accepted payment and the failed merchant change remain separate. Check the remaining eligible capture before reviewing compensation."}</p><div className="repair-dialog-note"><RotateCcw size={20}/><p>This check prepares an exact review. A refund or restoration needs its own consent on the next screen.</p></div><button className="button full" disabled={Boolean(busy)} onClick={() => submit({ kind: "prepare_compensation", amendmentId: amendment.proposal.id, purpose: dialog.purpose })}>Check current {dialog.purpose === "undo" ? "restoration" : "compensation"} <ArrowRight size={14}/></button></>}
    {dialog.kind === "next-sample" && commitment && <><p>Start a later Sample stock change on this same controlled commitment. A sourced replacement will cost $20 more. The existing allowance, including its pending and gross paid history, remains in force.</p><div className="repair-dialog-note"><ShieldCheck size={20}/><p>{policy ? `${currency(policy.remainingMinor)} remains of your ${currency(policy.capMinor)} limit. A qualifying change can run automatically under that existing scope; an over-limit change must wait.` : "No active kit allowance is present. The next proposal will need a separate exact decision."}</p></div><Consent checked={accepted} onChange={setAccepted}>Start this explicit Sample trigger on version {commitment.version}. It is not an authentic market notification and grants no new payment authority.</Consent><button className="button full" disabled={!accepted || Boolean(busy)} onClick={() => submit({ kind: "next_sample", commitmentId: commitment.id, expectedVersion: commitment.version, requestId: requestId.current, acceptSampleTrigger: true })}>Start the next Sample change <ArrowRight size={14}/></button></>}
    {dialog.kind === "support" && amendment && <><p>Save a review request beside this exact amendment, its payment history and any partial restoration. It stays in your private workspace; it does not contact a support service.</p><label className="repair-support-input">What needs review?<textarea rows={5} maxLength={2000} value={supportMessage} onChange={event => setSupportMessage(event.target.value)} placeholder="Describe the unresolved payment, stock or restoration question."/></label><small>{supportMessage.trim().length} / 2,000 characters</small><button className="button full" disabled={Boolean(busy) || supportMessage.trim().length < 10} onClick={() => submit({ kind: "support", amendmentId: amendment.proposal.id, requestId: requestId.current, message: supportMessage.trim() })}>Save a private review request <BookOpen size={14}/></button></>}
    {dialog.kind === "sample" && <><p>A separate Sample kit branch lets you follow the complete repair, payment, and compensation story. Your current workbench stays saved. Every engineering assertion and simulated payment is labelled Sample.</p><div className="repair-scenario-list" role="radiogroup" aria-label="Sample scenario">{SAMPLE_SCENARIOS.filter(value => value.id !== "followup-change").map(value => <label key={value.id} className={scenario === value.id ? "selected" : ""}><input type="radio" name="repair-scenario" value={value.id} checked={scenario === value.id} onChange={() => setScenario(value.id)}/><span><b>{value.title}</b><small>{value.detail}</small></span><span>{currency(value.deltaMinor)}</span></label>)}</div><Consent checked={accepted} onChange={setAccepted}>Create a separate Sample merchant commitment with no assumed base payment. This does not prove a real event, product specification, or human review.</Consent><button className="button full" disabled={!accepted || Boolean(busy)} onClick={() => submit({ kind: "sample", scenario, requestId: requestId.current, acceptSampleBranch: true })}>Start the Sample story <Play size={14}/></button></>}
    {dialog.kind === "baseline" && run && <><p>WorldKit Studio can demonstrate a whole-kit commitment using explicit test prices and zero test shipping and tax. Its starting version has no assumed payment, retailer order, or fulfillment. Any later positive amendment needs separate consent.</p><div className="repair-dialog-note"><Layers3 size={20}/><p>The real catalog observations and your original engineering evidence retain their labels. Open critical facts continue to block payments.</p></div><Consent checked={accepted} onChange={setAccepted}>Create this controlled Sample baseline and prepare a proposal for the selected exact alternative.</Consent><button className="button full" disabled={!accepted || Boolean(busy)} onClick={() => submit({ kind: "commitment", runId: run.id, graphHash: run.base.certificate.graphHash, acceptSampleCommitment: true })}>Prepare the exact proposal <ArrowRight size={14}/></button></>}
    {dialog.kind === "accept" && amendment && <><p>{dialog.authority === "policy" ? "Check this exact amendment against the separate kit allowance. Current scope, wallet consent, pending spend and gross history are reloaded before dispatch." : "This approval belongs only to the saved proposal below. The exact stock, price, critical facts and current commitment are checked again before payment."}</p><div className="repair-dialog-total"><span>Additional controlled cost</span><strong><MoneyDelta minor={amendment.proposal.quote.deltaMinor}/><small> USD</small></strong></div><div className="repair-dialog-binding"><Fingerprint size={15}/><div><b>Immutable proposal</b><code>{amendment.proposal.digest}</code><span>Controlled total {currency(amendment.proposal.quote.afterTotalMinor)} · quote ends {shortTime(amendment.proposal.expiresAt)}</span></div></div>{dialog.authority === "buyer" ? <PaymentMode mode={mode} onChange={setMode} sample={amendment.proposal.sourceMode === "sample"} ready={data?.readiness.paypal ?? false}/> : policy && <div className="repair-dialog-note"><ShieldCheck size={19}/><p><b>{currency(policy.remainingMinor)} remaining in this {policy.paymentMode === "sample" ? "Sample" : "PayPal sandbox"} allowance.</b> {currency(policy.pendingMinor)} is pending. Refunded spending still counts.</p></div>}<Consent checked={accepted} onChange={setAccepted}>I approve this exact controlled amendment using {allowanceMode === "sample" ? "the clearly labelled Sample payment simulator" : "PayPal sandbox"}. No retailer goods are ordered, and the digital-service policy grants no authority here.</Consent><button className="button full" disabled={!accepted || Boolean(busy) || amendment.proposal.technicalState !== "satisfied" || allowanceMode === "live_sandbox" && !data?.readiness.paypal} onClick={() => submit({ kind: "accept", amendmentId: amendment.proposal.id, proposalDigest: amendment.proposal.digest, paymentMode: allowanceMode, authority: dialog.authority, ...(dialog.authority === "policy" && policy ? { policyId: policy.id } : {}), acceptExactAmendment: true, acceptMerchantBoundary: true })}>{dialog.authority === "policy" ? "Check and apply within my limit" : allowanceMode === "sample" ? "Approve this Sample change" : "Continue to exact PayPal approval"}<ArrowRight size={14}/></button></>}
    {dialog.kind === "policy" && commitment && <><p>A fresh automatic allowance for additional changes to this controlled kit. A qualifying saved proposal may be applied as soon as this consent is saved. It preserves owned equipment, the original hard brief, listed sourcing retailers and equipment categories. Pending payments count. Refunds never restore the cap.</p><label className="repair-limit-input">Maximum additional gross spending · USD<div><span>$</span><input inputMode="decimal" type="number" min="1" max="1000" step="0.01" value={cap} onChange={event => setCap(event.target.value)}/></div></label><PaymentMode mode={mode} onChange={setMode} sample={commitment.branch === "sample_demonstration"} ready={data?.readiness.paypal ?? false}/>{mode === "live_sandbox" && <label>Current confirmed wallet<select value={walletId} onChange={event => setWalletId(event.target.value)}><option value="">Choose a current owned wallet</option>{wallets.map(wallet => <option key={wallet.id} value={wallet.id}>Confirmed wallet · {wallet.id.slice(-8)}</option>)}</select>{!wallets.length && <small>Connect and confirm a wallet in Studio first. Buyer approval for one exact change remains a separate option.</small>}</label>}<div className="repair-policy-scope"><span><b>Merchant</b> WorldKit Studio</span><span><b>Commitment</b> version {commitment.version}</span><span><b>Sourcing retailers</b> {[...new Set([...commitment.lines.map(line => line.domain), ...amendment?.proposal.quote.afterLines.map(line => line.domain) ?? []])].join(", ")}</span><span><b>Equipment categories</b> {[...new Set([...commitment.lines, ...amendment?.proposal.quote.afterLines ?? []].map(line => line.category))].join(", ")}</span><span><b>Conditions</b> {[...new Set([...commitment.lines, ...amendment?.proposal.quote.afterLines ?? []].map(line => line.condition ?? "unknown"))].join(", ")}</span><span><b>Ends</b> after 24 hours, wallet revocation, or fulfillment</span></div><Consent checked={accepted} onChange={setAccepted}>I authorize automatic controlled-kit changes within this additional gross limit, including the current qualifying proposal. A saved wallet alone and the earlier digital-service consent do not grant this scope.</Consent><button className="button full" disabled={!accepted || Boolean(busy) || !Number.isFinite(Number(cap)) || Number(cap) < 1 || Number(cap) > 1000 || mode === "live_sandbox" && (!wallet || !data?.readiness.paypal)} onClick={() => submit({ kind: "policy", requestId: requestId.current, amendmentId: amendment!.proposal.id, proposalDigest: amendment!.proposal.digest, commitmentId: commitment.id, expectedVersion: commitment.version, capMinor: Math.round(Number(cap) * 100), paymentMode: mode, ...(wallet && mode === "live_sandbox" ? { walletId: wallet.id, walletDigest: wallet.digest } : {}), acceptSeparateKitAuthority: true })}>Save the separate kit allowance <ShieldCheck size={14}/></button></>}
    {dialog.kind === "shipment" && commitment && <><p>Record an explicit simulated shipment for this Sample merchant commitment. This ends automatic kit-change authority and blocks conditional undo. No retailer shipment or parcel is created.</p><Consent checked={accepted} onChange={setAccepted}>Mark this controlled Sample kit as shipped and end its automatic changes.</Consent><button className="button full" disabled={!accepted || Boolean(busy)} onClick={() => submit({ kind: "sample_shipment", commitmentId: commitment.id, expectedVersion: commitment.version, acceptShipmentSimulation: true })}>Simulate shipment <PackageCheck size={14}/></button></>}
    {dialog.kind === "compensation" && request && <><p>{request.reason}</p><div className="repair-compensation-amounts"><div><span>Eligible refund</span><strong>{currency(request.refundMinor)}</strong><small>{currency(request.refundedMinor)} confirmed</small></div><div><span>Restoration supplement</span><strong>{currency(request.supplementalMinor)}</strong><small>Fresh buyer approval required</small></div></div><SourcePill source={request.paymentMode} payment/>{request.originalCheck && <div className="repair-dialog-note"><CheckCircle2 size={18}/><p>Original exact stock, cost and critical facts checked {shortTime(request.originalCheck.checkedAt)}. They are checked again before restoring the commitment.</p></div>}{request.creditShortfallMinor > 0 && <div className="repair-dialog-note"><CircleHelp size={18}/><p>{currency(request.creditShortfallMinor)} of the demonstration credit has no eligible funded capture. No extra cash refund is implied; this portion needs support review.</p></div>}<div className="repair-dialog-binding"><Fingerprint size={15}/><div><b>Separate compensation consent</b><code>{request.digest}</code><span>{request.state.replaceAll("_", " ")}</span></div></div>{!request.consentedAt ? <><Consent checked={accepted} onChange={setAccepted}>I approve these exact compensation amounts. Restoration is conditional on current stock, cost, technical feasibility and fulfillment; a completed refund stays recorded even if restoration fails.</Consent><button className="button full" disabled={!accepted || Boolean(busy)} onClick={() => submit({ kind: "accept_compensation", compensationId: request.id, compensationDigest: request.digest, acceptExactCompensation: true, acceptConditionalRestoration: true })}>{request.supplementalMinor ? "Approve the restoration supplement" : request.kind === "undo" ? "Approve conditional undo" : "Approve separate compensation"}<ArrowRight size={14}/></button></> : <><button className="button subtle full" disabled={Boolean(busy)} onClick={() => submit({ kind: "reconcile_compensation", compensationId: request.id })}><RefreshCw size={14}/> Reconcile the original operation</button>{["refund_pending", "payment_pending"].includes(request.state) && <button className="text-button" disabled={Boolean(busy)} onClick={() => submit({ kind: "resume_compensation", compensationId: request.id, compensationDigest: request.digest, continueSavedApproval: true })}>Continue saved compensation <ArrowRight size={12}/></button>}{request.supplementalOrderId && data?.orders.find(order => order.id === request.supplementalOrderId)?.approvalUrl && <a className="button paypal-button full" href={data.orders.find(order => order.id === request.supplementalOrderId)!.approvalUrl!} rel="noreferrer">Continue restoration in PayPal <ExternalLink size={13}/></a>}{request.state === "requires_payment_approval" && <button className="text-button" disabled={Boolean(busy)} onClick={() => submit({ kind: "capture_restoration", compensationId: request.id, acceptExactCapture: true })}>Confirm approved restoration payment <ArrowRight size={12}/></button>}</>}</>}
    {error && <div className="repair-dialog-error" role="alert"><CircleHelp size={16}/><p>{error}</p></div>}{busy && <Busy text={busy}/>}<p className="repair-dialog-footnote">Only this private workbench receives notifications. No external support message or retailer action is sent.</p>
  </ModalFrame>;
}
function Consent({ checked, onChange, children }: { checked: boolean; onChange: (value: boolean) => void; children: React.ReactNode }) { return <label className="repair-consent"><input type="checkbox" checked={checked} onChange={event => onChange(event.target.checked)}/><span>{children}</span></label>; }
function PaymentMode({ mode, onChange, sample, ready }: { mode: "sample" | "live_sandbox"; onChange: (value: "sample" | "live_sandbox") => void; sample: boolean; ready: boolean }) { return <fieldset className="repair-payment-mode"><legend>Choose the payment evidence</legend>{sample && <label className={mode === "sample" ? "selected" : ""}><input type="radio" name="repair-payment-mode" checked={mode === "sample"} onChange={() => onChange("sample")}/><span><b>Sample payment simulator</b><small>Local persisted receipts. No PayPal call or money movement.</small></span></label>}<label className={`${mode === "live_sandbox" ? "selected" : ""} ${!ready ? "unavailable" : ""}`}><input type="radio" name="repair-payment-mode" checked={mode === "live_sandbox"} disabled={!ready} onChange={() => onChange("live_sandbox")}/><span><b>PayPal sandbox</b><small>{ready ? "Actual sandbox create and capture, with separate fresh approval." : "Not configured in this environment. The proposal stays saved."}</small></span></label></fieldset>; }
